/**
 * Built-in English → Japanese dictionary used by the tap-to-lookup word popover
 * (services/wordLookup) for words that are neither in a material's vocabulary nor in the
 * vocabulary bank. Entries are base forms; inflected forms are resolved by lemmaCandidates.
 * Covers every word in the Reading and TOEIC passages (plus the materials' key vocabulary) —
 * `npm run validate-content` warns when new content introduces a word that nothing covers.
 *
 * Format: headword (lowercase) → [part of speech, Japanese meaning, standard example (EN),
 * its translation (JA), common collocations]. The example is a plain, general-purpose sentence
 * written for the word itself — never a sentence taken from a passage — so the word is learned
 * independently of any one text. Proper nouns, symbols and prefixes have no example.
 */
export type DictionaryEntry = readonly [
  partOfSpeech: string,
  meaningJa: string,
  standardExampleEn?: string,
  standardExampleJa?: string,
  collocations?: readonly string[],
];

